/// A few lines of verse and who wrote them. Roman Urdu is written the way
/// people type it, not in a scholarly transliteration.
pub struct Poem {
    pub id: &'static str,
    pub poet: &'static str,
    pub lines: &'static [&'static str],
    /// "urdu" or "english".
    pub language: &'static str,
}

const fn urdu(id: &'static str, poet: &'static str, lines: &'static [&'static str]) -> Poem {
    Poem { id, poet, lines, language: "urdu" }
}

const fn english(id: &'static str, poet: &'static str, lines: &'static [&'static str]) -> Poem {
    Poem { id, poet, lines, language: "english" }
}

