/// A motivational line and who said it, with where when it is known.
pub struct Quote {
    pub id: &'static str,
    pub text: &'static str,
    pub who: &'static str,
}

const fn quote(id: &'static str, text: &'static str, who: &'static str) -> Quote {
    Quote { id, text, who }
}

